class FakeProvider implements AgentProvider{
  readonly capabilities={supportsMcpEvents:true,supportsEmotionRendering:true};tasks=new Map<string,DeckTask>();calls=0;prompts:string[]=[];inputs:CreateTaskInput[]=[];deletedSessions:string[]=[];health:{ok:boolean;detail:unknown}={ok:true,detail:{category:"ready"}};
  constructor(readonly id:ProviderId,public fail=false,public replies:string[]=[]){ }
  listTasks(){return Promise.resolve([...this.tasks.values()]);}getTask(task:DeckTask){return Promise.resolve(this.tasks.get(task.id)??task);}
  /** Set to a pending promise to keep a run (and therefore its workspace lease) in flight. */
  hold:Promise<void>|null=null;
  async createTask(input:CreateTaskInput){this.calls++;this.prompts.push(input.prompt);this.inputs.push(input);if(this.hold)await this.hold;const timestamp=new Date().toISOString(),id=`${this.id}:${crypto.randomUUID()}`,failed=this.fail,task:DeckTask={id,provider:this.id,nativeId:id,threadId:crypto.randomUUID(),projectId:input.project.id,title:input.title??"task",prompt:input.prompt,status:failed?"failed":"completed",createdAt:timestamp,updatedAt:timestamp,result:failed?null:this.replies[this.calls-1]??`${this.id} actual final ${this.calls}`,error:failed?`${this.id} failed`:null,log:"",owned:true,pid:null,pgid:null,processStart:null,commandMarker:null,parentThreadId:null,executionHostId:"local",workspaceId:"w",providerSessionId:null,requestedModel:input.model,requestedReasoningEffort:input.reasoningEffort,requestedServiceTier:input.serviceTier};task.providerSessionId=task.threadId;this.tasks.set(id,task);return Promise.resolve(task);}
  sendMessage(task:DeckTask,prompt:string){this.calls++;this.prompts.push(prompt);const next={...task,prompt,status:"completed" as const,result:this.replies[this.calls-1]??`${this.id} final follow-up ${this.calls}`,updatedAt:new Date().toISOString()};this.tasks.set(next.id,next);return Promise.resolve(next);}compactThread(task:DeckTask){return Promise.resolve(task);}forkThread(task:DeckTask){return Promise.resolve(task);}stopTask(task:DeckTask){const next={...task,status:"stopped" as const};this.tasks.set(task.id,next);return Promise.resolve(next);}deleteSession(task:DeckTask){this.deletedSessions.push(task.threadId!);for(const[id,item]of this.tasks)if(item.threadId===task.threadId)this.tasks.delete(id);return Promise.resolve({threadId:task.threadId!,deleted:true,deletedTasks:1});}healthCheck(){return Promise.resolve(this.health);}
}
