/** Waits until the expected number of unreleased write leases is visible. */
async function heldWriteLeases(f:Fixture,expected:number){
  for(let i=0;i<300;i++){const held=(await f.db.listCollaborationLeases("w")).filter(item=>!item.releasedAt&&item.mode==="write");if(held.length>=expected)return held;await new Promise(resolve=>setTimeout(resolve,20));}
  throw new Error("workspace write lease was never observed");
}
