  it("applies roster changes to later automatic rounds without renumbering history",async()=>{const f=await fixture();try{const created=await f.orchestrator.create({...input("debate"),conversationFlow:"automatic",conversationKind:"casual",maxRounds:1,maxTurnsPerParticipant:undefined,participantOrder:["codex","claude"]});let detail=await terminal(f.orchestrator,created.session.id);for(let i=0;i<50&&(f.orchestrator as any).active.has(created.session.id);i++)await new Promise(resolve=>setTimeout(resolve,10));await f.orchestrator.setConversationParticipant(created.session.id,"claude",false);await f.orchestrator.addConversationRounds(created.session.id,1);detail=await terminal(f.orchestrator,created.session.id);expect(detail.runs.filter((run:any)=>run.round===2)).toHaveLength(1);for(let i=0;i<50&&(f.orchestrator as any).active.has(created.session.id);i++)await new Promise(resolve=>setTimeout(resolve,10));await f.orchestrator.setConversationParticipant(created.session.id,"claude",true);await f.orchestrator.addConversationRounds(created.session.id,1);detail=await terminal(f.orchestrator,created.session.id);const providerByParticipant=new Map(detail.participants.map((item:any)=>[item.id,item.provider]));expect(detail.runs.map((run:any)=>[run.sequence,run.round,providerByParticipant.get(run.participantId)])).toEqual([[1,1,"codex"],[2,1,"claude"],[3,2,"codex"],[4,3,"codex"],[5,3,"claude"]]);expect(detail.session).toMatchObject({status:"completed",outcome:"turn-limit",metadata:{currentRound:3}});}finally{await f.db.close();}});
