  it("persists compact conversation length across follow-up while keeping markers out of relay prompts",async()=>{const f=await fixture();try{f.codex.replies=["[[e:happy]]\n첫 답변", "[[e:thinking]]\n둘째 답변"];const base=input("debate"),created=await f.orchestrator.create({...base,participants:[base.participants[0]],conversationFlow:"guided",conversationKind:"casual",conversationTurnLength:"compact",participantOrder:["codex"],maxRounds:2,maxTurnsPerParticipant:undefined}),first=await waiting(f.orchestrator,created.session.id);expect(first.session.metadata.conversationTurnLength).toBe("compact");expect(f.codex.prompts[0]).toContain("inline emotion scene mode: compact");await f.orchestrator.submitConversationMessage(created.session.id,"다음 이야기",first.session.controllerGeneration);const done=await terminal(f.orchestrator,created.session.id);expect(done.session.metadata.conversationTurnLength).toBe("compact");expect(f.codex.prompts[1]).toContain("inline emotion scene mode: compact");expect(f.codex.prompts[1]).toContain("첫 답변");expect(f.codex.prompts[1]).not.toContain("[[e:happy]]");expect(Object.values(done.runOutputs).some(value=>String(value).includes("[[e:happy]]"))).toBe(true);}finally{await f.db.close();}});
  it("enforces Debate turn limits in the DB transaction and cancels every active provider run",async()=>{const f=await fixture();try{const timestamp=new Date().toISOString(),session:any={id:crypto.randomUUID(),projectId:"p",title:"debate",mode:"debate",status:"starting",outcome:null,primaryParticipantId:null,maxCalls:10,currentCallCount:0,currentStep:"queued",maxTurnsPerParticipant:1,currentTurnCounts:{claude:0,codex:0},timeoutAt:"2099-01-01T00:00:00.000Z",controllerGeneration:1,workChainId:null,sourceTaskId:null,createdAt:timestamp,updatedAt:timestamp,completedAt:null,cancelledAt:null,archivedAt:null,metadata:{debateKind:"discussion"}};await f.db.upsertCollaborationSession(session);const makeParticipant=async(provider:"codex"|"claude")=>f.db.upsertCollaborationParticipant({id:crypto.randomUUID(),collaborationSessionId:session.id,provider,role:provider==="codex"?"primary":"debater",executionHostId:"local",workspaceId:"w",providerSessionId:crypto.randomUUID(),sourceTaskId:null,permissionMode:"read",status:"running",sessionGeneration:1,capabilitySnapshot:{},createdAt:timestamp,updatedAt:timestamp,archivedAt:null});const codexParticipant:any=await makeParticipant("codex"),claudeParticipant:any=await makeParticipant("claude");await f.db.upsertCollaborationSession({...session,primaryParticipantId:codexParticipant.id});const makeRun=async(participant:any,sequence:number)=>{const run:any=await f.db.createCollaborationRun({id:crypto.randomUUID(),collaborationSessionId:session.id,participantId:participant.id,round:1,sequence,attempt:1,purpose:"debate-turn",sourceParticipantId:null,targetParticipantId:participant.id,providerTaskId:null,status:"queued",deadlineAt:session.timeoutAt,inputChecksum:"x",relayArtifactId:null,generation:1,lastEventSequence:0,errorCategory:null,startedAt:null,completedAt:null,failedAt:null,cancelledAt:null,createdAt:timestamp,updatedAt:timestamp});const provider=participant.provider==="codex"?f.codex:f.claude,task=await provider.createTask({project:{id:"p",name:"p",path:f.root,realPath:f.root,enabled:true,error:null},prompt:"running",executionHostId:"local",workspaceId:"w"}),running={...task,status:"running" as const};provider.tasks.set(task.id,running);await f.db.upsertTask(running);return f.db.upsertCollaborationRun({...run,providerTaskId:task.id,status:"running",startedAt:timestamp});};await makeRun(codexParticipant,1);await expect(f.db.createCollaborationRun({id:crypto.randomUUID(),collaborationSessionId:session.id,participantId:codexParticipant.id,round:2,sequence:3,attempt:1,purpose:"debate-turn",sourceParticipantId:claudeParticipant.id,targetParticipantId:codexParticipant.id,providerTaskId:null,status:"queued",deadlineAt:session.timeoutAt,inputChecksum:"y",relayArtifactId:null,generation:2,lastEventSequence:0,errorCategory:null,startedAt:null,completedAt:null,failedAt:null,cancelledAt:null,createdAt:timestamp,updatedAt:timestamp})).rejects.toThrow(/turn limit/i);await makeRun(claudeParticipant,2);const detail=await f.orchestrator.cancel(session.id);expect(detail.session.status).toBe("cancelled");expect(detail.runs.every((run:any)=>run.status==="cancelled")).toBe(true);expect([...f.codex.tasks.values(),...f.claude.tasks.values()].every(task=>task.status==="stopped")).toBe(true);}finally{await f.db.close();}});
  it("acquires read/read, read/write and write/write leases in one workspace and reports the concurrent set",async()=>{const f=await fixture();try{
    const base={workspaceId:"w",collaborationSessionId:"c",participantId:"p",leaseGeneration:2,heartbeatAt:"2026-01-01T00:00:00Z",expiresAt:"2099-01-01T00:00:00Z",acquiredAt:"2026-01-01T00:00:00Z"};
    const writer:any=await f.db.acquireCollaborationLease({id:"l1",...base,ownerRunId:"r1",mode:"write"});
    const secondWriter:any=await f.db.acquireCollaborationLease({id:"l2",...base,collaborationSessionId:"c2",ownerRunId:"r2",mode:"write"});
    const reader:any=await f.db.acquireCollaborationLease({id:"l3",...base,collaborationSessionId:"c3",ownerRunId:"r3",mode:"read"});
    expect([writer.acquired,secondWriter.acquired,reader.acquired]).toEqual([true,true,true]);
    expect(writer.concurrent).toEqual([]);
    expect(secondWriter.concurrent.map((item:any)=>[item.id,item.mode])).toEqual([["l1","write"]]);
    expect(reader.concurrent.map((item:any)=>[item.id,item.mode])).toEqual([["l1","write"],["l2","write"]]);
    // Advisory data carries identity and timing only, never prompts or content.
    expect(Object.keys(reader.concurrent[0]).sort()).toEqual(["acquiredAt","collaborationSessionId","expiresAt","id","mode","ownerRunId","participantId","workspaceId"]);
    // Heartbeats and releases stay per-lease: one owner cannot renew or end another's.
    expect(await f.db.heartbeatCollaborationLease({id:"l1",ownerRunId:"r1",leaseGeneration:1,heartbeatAt:"2026",expiresAt:"2099"})).toBe(false);
    expect(await f.db.heartbeatCollaborationLease({id:"l1",ownerRunId:"r2",leaseGeneration:2,heartbeatAt:"2026",expiresAt:"2099"})).toBe(false);
    expect(await f.db.heartbeatCollaborationLease({id:"l1",ownerRunId:"r1",leaseGeneration:2,heartbeatAt:"2026",expiresAt:"2099"})).toBe(true);
    await f.db.releaseCollaborationLeases({ownerRunId:"r1",releasedAt:"2026-01-01T00:01:00Z",status:"released"});
    const active=(await f.db.listCollaborationLeases("w")).filter(item=>!item.releasedAt).map(item=>item.id).sort();
    expect(active).toEqual(["l2","l3"]);
    expect(await f.db.heartbeatCollaborationLease({id:"l2",ownerRunId:"r2",leaseGeneration:2,heartbeatAt:"2026",expiresAt:"2099"})).toBe(true);
  }finally{await f.db.close();}});
  it("starts a second full/write managed writer while the first still holds the workspace",async()=>{const f=await fixture();try{
    const source=await fullAccessSource(f),bridge=managedBridge(f),audits=vi.spyOn(f.db,"appendAudit");
    let release=()=>{};f.codex.hold=new Promise<void>(resolve=>{release=()=>resolve();});
    const first=bridge.create(source,{provider:"codex",prompt:"implement A",automationLevel:"full",idempotencyKey:crypto.randomUUID()});
    await heldWriteLeases(f,1);
    // The Codex writer is mid-run and holding a write lease; the Claude writer
    // must still be created, dispatched and finish on its own thread.
    const second=await bridge.create(source,{provider:"claude",prompt:"implement B",automationLevel:"full",idempotencyKey:crypto.randomUUID()});
    expect(second).toMatchObject({provider:"claude",ownership:"claudex-workhouse",status:"completed",threadId:expect.any(String)});
    expect(f.claude.inputs[0]).toMatchObject({permissionProfile:":danger-full-access",automationLevel:"full"});
    // The concurrent writer is observed, not blocked.
    const observation=(await f.orchestrator.detail(second.collaborationId!)).messages.find((item:any)=>item.messageType==="workspace-concurrency");
    const advisory=JSON.parse(observation!.contentRef);
    expect(advisory).toMatchObject({workspaceId:"w",selfMode:"write",concurrentWriters:1,concurrentReaders:0});
    expect(advisory.concurrent[0]).toMatchObject({mode:"write",collaborationSessionId:expect.any(String),ownerRunId:expect.any(String),acquiredAt:expect.any(String)});
    expect(JSON.stringify(advisory)).not.toContain("implement A");
    expect(audits.mock.calls.map(([entry]:any[])=>entry.action)).toContain("workspace-concurrent-execution");
    expect(audits.mock.calls.find(([entry]:any[])=>entry.action==="workspace-concurrent-execution")![0]).toMatchObject({workspaceId:"w",outcome:"success",detail:expect.stringContaining("concurrentWriters=1")});
    expect(f.claude.prompts[0]).toContain("shared-workspace write contract");
    expect(f.claude.prompts[0]).toContain("owned by another session");
    expect(f.claude.prompts[0]).toContain("1 writer(s)");
    release();
    const firstSnapshot=await first;
    expect(firstSnapshot).toMatchObject({provider:"codex",status:"completed",threadId:expect.any(String)});
    expect(firstSnapshot.taskId).not.toBe(second.taskId);
    expect(firstSnapshot.threadId).not.toBe(second.threadId);
    expect(firstSnapshot.collaborationId).not.toBe(second.collaborationId);
    for(const id of [firstSnapshot.collaborationId!,second.collaborationId!]){
      const detail=await terminal(f.orchestrator,id);
      expect(detail.session.status).toBe("completed");
      expect(detail.runs.every((run:any)=>run.errorCategory!=="WORKSPACE_LEASE_CONFLICT")).toBe(true);
    }
    expect((await f.db.listCollaborationLeases("w")).every(item=>item.releasedAt)).toBe(true);
  }finally{await f.db.close();}});

  it("starts a same-provider and every other provider writer against one busy workspace",async()=>{const f=await fixture();try{
    const source=await fullAccessSource(f,"claude"),bridge=managedBridge(f);
    let release=()=>{};f.claude.hold=new Promise<void>(resolve=>{release=()=>resolve();});
    // Same provider as the source and as the in-flight writer: still a distinct managed session.
    const held=bridge.create(source,{provider:"claude",prompt:"claude writer 1",automationLevel:"full",idempotencyKey:crypto.randomUUID()});
    await heldWriteLeases(f,1);
    const others=[] as any[];
    for(const provider of ["codex","deepseek","ollama","grok","antigravity"] as const)others.push(await bridge.create(source,{provider,prompt:`${provider} writer`,automationLevel:"full",idempotencyKey:crypto.randomUUID()}));
    release();
    const first=await held,everyWriter=[first,...others];
    expect(everyWriter.map(item=>item.provider)).toEqual(["claude","codex","deepseek","ollama","grok","antigravity"]);
    expect(everyWriter.every(item=>item.status==="completed")).toBe(true);
    expect(new Set(everyWriter.map(item=>item.taskId)).size).toBe(6);
    expect(new Set(everyWriter.map(item=>item.threadId)).size).toBe(6);
    expect(new Set(everyWriter.map(item=>item.collaborationId)).size).toBe(6);
    for(const item of everyWriter)expect((await terminal(f.orchestrator,item.collaborationId!)).session).toMatchObject({status:"completed",outcome:"assist-completed"});
  }finally{await f.db.close();}});

  it("selects read or full managed automation under the source ceiling and refuses escalation",async()=>{const f=await fixture();try{
    const full=await fullAccessSource(f),bridge=managedBridge(f);
    const review=await bridge.create(full,{provider:"claude",prompt:"review only",automationLevel:"read",idempotencyKey:crypto.randomUUID()});
    expect(review.status).toBe("completed");
    expect(f.claude.inputs[0]).toMatchObject({permissionProfile:":read-only",automationLevel:"read"});
    expect((await f.orchestrator.detail(review.collaborationId!)).participants.find((item:any)=>item.provider==="claude")).toMatchObject({permissionMode:"read"});
    // A read target carries no write contract.
    expect(f.claude.prompts[0]).not.toContain("shared-workspace write contract");
    const implement=await bridge.create(full,{provider:"claude",prompt:"implement it",automationLevel:"full",idempotencyKey:crypto.randomUUID()});
    expect(f.claude.inputs[1]).toMatchObject({permissionProfile:":danger-full-access",automationLevel:"full"});
    expect(implement.taskId).not.toBe(review.taskId);
    // Omitted level keeps inheriting the source's effective mode.
    const inherited=await bridge.create(full,{provider:"claude",prompt:"inherit",idempotencyKey:crypto.randomUUID()});
    expect(f.claude.inputs[2]).toMatchObject({permissionProfile:":danger-full-access",automationLevel:"full"});
    expect(inherited.status).toBe("completed");
    const readOnlySource=await f.db.upsertTask({...full,id:"codex:read-source",nativeId:"codex:read-source",permissionProfile:":read-only",metadata:{automationLevel:"read",workMode:"plan"}});
    await expect(bridge.create(readOnlySource,{provider:"claude",prompt:"escalate",automationLevel:"full",idempotencyKey:crypto.randomUUID()})).rejects.toMatchObject({code:"AUTOMATION_LEVEL_ESCALATION_DENIED",statusCode:403});
    await expect(bridge.create(readOnlySource,{provider:"claude",prompt:"escalate",automationLevel:"auto",idempotencyKey:crypto.randomUUID()})).rejects.toMatchObject({code:"AUTOMATION_LEVEL_ESCALATION_DENIED"});
    expect(await bridge.create(readOnlySource,{provider:"claude",prompt:"stay read",automationLevel:"read",idempotencyKey:crypto.randomUUID()})).toMatchObject({status:"completed"});
  }finally{await f.db.close();}});

  it("still collapses a repeated idempotency key while independent keys create parallel workspace tasks",async()=>{const f=await fixture();try{
    const source=await fullAccessSource(f),bridge=managedBridge(f),request={provider:"claude" as const,prompt:"implement",automationLevel:"full" as const,idempotencyKey:crypto.randomUUID()};
    const first=await bridge.create(source,request),replay=await bridge.create(source,request);
    expect(replay).toEqual(first);
    expect(f.claude.calls).toBe(1);
    await expect(bridge.create(source,{...request,prompt:"different body"})).rejects.toMatchObject({statusCode:409});
    const independent=await bridge.create(source,{...request,idempotencyKey:crypto.randomUUID()});
    expect(independent.taskId).not.toBe(first.taskId);
    expect(independent.collaborationId).not.toBe(first.collaborationId);
    expect(f.claude.calls).toBe(2);
  }finally{await f.db.close();}});

  it("snapshots the global interface locale and keeps English roleplay multilingual",async()=>{const f=await fixture();try{await f.db.putSystemSetting("ui.locale",{locale:"en"},new Date().toISOString());const base=input("debate"),created=await f.orchestrator.create({...base,prompt:"Write a sweet romance.",participants:[{...base.participants[0],tonePreset:"lewd-guardian-comedy" as const}],conversationFlow:"guided",conversationKind:"casual",participantOrder:["codex"],maxRounds:2,maxTurnsPerParticipant:undefined}),first=await waiting(f.orchestrator,created.session.id),firstPrompt=f.codex.prompts[0];expect(first.session.metadata).toMatchObject({conversationLocale:"en",userNickname:"User"});expect(firstPrompt).toContain("language used by the latest user-authored message");expect(firstPrompt).toContain("default to the session interface language: English");expect(firstPrompt).toContain("Respond in the active conversation language, in-character");expect(firstPrompt).not.toContain("Respond in Korean");await f.orchestrator.submitConversationMessage(created.session.id,"They are high-school students going home after the festival.",first.session.controllerGeneration);await terminal(f.orchestrator,created.session.id);const minorPrompt=f.codex.prompts[1];expect(minorPrompt).toContain("TURN STATE — MINOR SAFETY EXIT");expect(minorPrompt).toContain("translate and adapt the one-line burst into the active conversation language");expect(minorPrompt).not.toContain("blurt out the direct non-graphic sexual conclusion yourself");}finally{await f.db.close();}});
